# Builds the benchmark programs of benchmarks/ with one compiler into a folder of finished .exe files, for a computer that has no compiler (see
# run_prebuilt.ps1). Used by the workflow bench-build.yml.
#   powershell -File benchmarks\build_prebuilt.ps1 -Blitzcc <path of blitzcc.exe> -Out <folder>
param([Parameter(Mandatory)] $Blitzcc, [Parameter(Mandatory)] $Out)
$ErrorActionPreference = "Stop"
$here = Split-Path -Parent $MyInvocation.MyCommand.Path
New-Item -ItemType Directory -Force $Out | Out-Null
$work = Join-Path ([IO.Path]::GetTempPath()) ("bench-" + [guid]::NewGuid())
New-Item -ItemType Directory -Force $work | Out-Null
& $Blitzcc -v | Out-File (Join-Path $Out "compiler.txt")
foreach ($name in "emitted", "flythrough", "waterfall", "dungeon", "forest") {
    $dir = Join-Path $work $name
    New-Item -ItemType Directory -Force $dir | Out-Null
    Copy-Item (Join-Path $here "$name.bb") $dir
    $counters = Join-Path $here "${name}_llvm.bi"
    if (Test-Path $counters) { Copy-Item $counters (Join-Path $dir "${name}_counters.bi") }
    Push-Location $dir
    & $Blitzcc -q -o (Join-Path $Out "$name.exe") (Join-Path $dir "$name.bb")
    $code = $LASTEXITCODE
    Pop-Location
    if ($code -ne 0) { throw "Building $name failed (exit code $code)" }
}
Remove-Item -Recurse -Force $work
